import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import "./globals.css";
import { ThemeProvider } from "@/components/theme-provider";

import { CommandPaletteProvider } from "@/hooks/use-command-palette";
import { SearchDialog } from "@/components/dashboard/search-dialog";
import { QuickCreateDialog } from "@/components/dashboard/quick-create-dialog";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

export const metadata: Metadata = {
  title: "Murgodash Playground",
  description: "Ultimate Bento Dashboard Template",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html
      lang="fr"
      suppressHydrationWarning
      className={`${geistSans.variable} ${geistMono.variable} h-full antialiased`}
    >
      <body className="min-h-full flex flex-col">
        <ThemeProvider
          attribute="class"
          defaultTheme="system"
          enableSystem
          disableTransitionOnChange
        >
          <CommandPaletteProvider>
            {children}
            <SearchDialog />
            <QuickCreateDialog />
          </CommandPaletteProvider>
        </ThemeProvider>
      </body>
    </html>
  );
}
